 Future<void> _addRecord(RecordType type)async{
  final title=TextEditingController(),value=TextEditingController(),notes=TextEditingController(),region=TextEditingController(),movement=TextEditingController(),protocol=TextEditingController();
  final unit=TextEditingController();String side='Não se aplica';double pain=0;int? strengthGrade;
  final ok=await showDialog<bool>(context:context,builder:(context)=>StatefulBuilder(builder:(context,setLocal)=>AlertDialog(
   title:Text('Nova ${_label(type)}'),
   content:SizedBox(width:480,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[
    TextField(controller:title,decoration:const InputDecoration(labelText:'Título / teste *')),
    if(type==RecordType.goniometry||type==RecordType.strength)...[
     const SizedBox(height:10),TextField(controller:region,decoration:const InputDecoration(labelText:'Região / articulação *')),
     const SizedBox(height:10),TextField(controller:movement,decoration:InputDecoration(labelText:type==RecordType.goniometry?'Movimento *':'Músculo / grupo muscular *')),
     const SizedBox(height:10),DropdownButtonFormField<String>(initialValue:side,decoration:const InputDecoration(labelText:'Lado'),items:['Direito','Esquerdo','Bilateral','Não se aplica'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setLocal(()=>side=v!)),
    ],
    const SizedBox(height:10),
    if(type==RecordType.strength)
     DropdownButtonFormField<int>(initialValue:strengthGrade,decoration:const InputDecoration(labelText:'Grau de força *',helperText:'Escala de 0 a 5'),items:List.generate(6,(i)=>DropdownMenuItem(value:i,child:Text('$i / 5'))),onChanged:(v)=>setLocal((){strengthGrade=v;value.text=v?.toString()??'';}))
    else
     TextField(controller:value,keyboardType:(type==RecordType.goniometry||type==RecordType.functionalTest)?const TextInputType.numberWithOptions(decimal:true):null,inputFormatters:(type==RecordType.goniometry||type==RecordType.functionalTest)?[FilteringTextInputFormatter.allow(RegExp(r'^\d{0,6}([,.]\d{0,2})?$'))]:null,decoration:InputDecoration(labelText:type==RecordType.goniometry?'Amplitude (graus) *':type==RecordType.functionalTest?'Resultado numérico *':'Resultado / registro *',suffixText:type==RecordType.goniometry?'°':null,helperText:type==RecordType.goniometry?'Somente números. Ex.: 90':type==RecordType.functionalTest?'Somente números. Informe a unidade abaixo.':null)),
    if(type==RecordType.functionalTest)...[const SizedBox(height:10),TextField(controller:unit,decoration:const InputDecoration(labelText:'Unidade *',hintText:'Ex.: s, m, repetições')),const SizedBox(height:10),TextField(controller:protocol,decoration:const InputDecoration(labelText:'Protocolo / referência'))],
    if(type==RecordType.assessment||type==RecordType.evolution)...[const SizedBox(height:12),Text('Dor (EVA): ${pain.round()}/10'),Slider(value:pain,min:0,max:10,divisions:10,onChanged:(v)=>setLocal(()=>pain=v))],
    const SizedBox(height:10),TextField(controller:notes,maxLines:4,decoration:const InputDecoration(labelText:'Observações clínicas')),
   ]))),
   actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Salvar'))]
  )));
  if(ok!=true||title.text.trim().isEmpty)return;
  if(type==RecordType.strength&&strengthGrade==null){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Selecione o grau de força de 0 a 5.')));return;}
  if(value.text.trim().isEmpty)return;
  if((type==RecordType.goniometry||type==RecordType.strength)&&(region.text.trim().isEmpty||movement.text.trim().isEmpty))return;
  if((type==RecordType.goniometry||type==RecordType.functionalTest)&&double.tryParse(value.text.trim().replaceAll(',','.'))==null){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(type==RecordType.goniometry?'Informe uma amplitude numérica válida para a goniometria.':'Informe um resultado numérico válido para o teste funcional.')));return;}
  if(type==RecordType.functionalTest&&unit.text.trim().isEmpty){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Informe a unidade do teste funcional.')));return;}
